"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[274],{32947:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"\\t\\nCreates a new Processor object.\\n- `Callback` ((Event: Types.Process) -> boolean): The callback function to process the events.\\n\\t- `Config` (table, optional): The configuration for the Processor.\\n\\t- `Size` (number, optional): The number of requests to process at once. Defaults to 20\\n\\t- `Delay` (number, optional): The delay between each batch. Defaults to 30\\n\\t- `SavedRequestsPerPlayer` (number): The number of requests per player to save for other libraries. Defaults to 2. (Change this at your own risk, as it can lead to api rate limiting)\\n\\nThe Processor object processes events in a queue, in a batch like manor, with a delay between each batch.\\nThe Processor object will attempt to process all events in the queue, in the event of a server shutdown.","params":[{"name":"Callback","desc":"","lua_type":"(Event: Types.Process) -> boolean"},{"name":"Config","desc":"","lua_type":"{ Size: number?, Delay: number? }?"},{"name":"SavedRequestsPerPlayer","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"Processor"}],"function_type":"static","source":{"line":31,"path":"src/Processor/init.luau"}}],"properties":[],"types":[],"name":"Processor","desc":"Processor object for managing the processing of events.\\n\\t","source":{"line":10,"path":"src/Processor/init.luau"}}')}}]);